import csv, json
from datetime import date

AUDIT = date(2026, 3, 31)

# Load register
reg = {}
with open('/app/input/licensed_property_register.csv') as f:
    for r in csv.DictReader(f):
        reg[r['license_id']] = {
            'license_type': r['license_type'],
            'covers_distribution': r['covers_distribution'],
            'valid_until': date.fromisoformat(r['valid_until']),
            'property_name': r['property_name'],
        }

# Load accounts
accs = {}
with open('/app/input/client_accounts.csv') as f:
    for r in csv.DictReader(f):
        accs[r['account_id']] = {
            'account_type': r['account_type'],
            'master_agreement_covers': r['master_agreement_covers'],
            'agreement_status': r['agreement_status'],
            'account_name': r['account_name'],
        }

def dist_covered(covers_field, dist):
    if covers_field == 'all':
        return True
    return dist in covers_field.split(';')

def licence_covers(lic_id, lic_type, dist):
    if lic_id == 'none' or lic_id == '':
        return False
    if lic_id not in reg:
        return False
    L = reg[lic_id]
    if L['license_type'] != lic_type:
        return False
    if not dist_covered(L['covers_distribution'], dist):
        return False
    if L['valid_until'] < AUDIT:
        return False
    return True

def acct_clears_channel(acct, dist):
    # §6: public/paid channel cleared only if active AND covers names dist
    if acct['agreement_status'] != 'active':
        return False
    cov = acct['master_agreement_covers']
    if cov == 'none':
        return False
    return dist in cov.split(';')

# Load requests
reqs = []
with open('/app/input/composite_request_log.csv') as f:
    for r in csv.DictReader(f):
        reqs.append(r)

results = {}
for r in reqs:
    rid = r['request_id']
    dist = r['intended_distribution']
    findings = []

    # §3 character
    if r['character_property'] != 'none':
        cleared = False
        # licence
        if licence_covers(r['character_license_id'], 'character', dist):
            cleared = True
        # allowance
        if dist == 'personal_only':
            cleared = True
        if not cleared:
            findings.append('UNLICENSED_CHARACTER_USE')

    # §4 background
    bs = r['background_source']
    if bs == 'customer_original':
        pass
    elif bs == 'third_party_unlicensed':
        findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    elif bs == 'third_party_licensed':
        if not licence_covers(r['background_license_id'], 'background', dist):
            findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')

    # §5 minor consent
    if r['subject_is_minor'] == 'True':
        ok = True
        if r['minor_consent_type'] == 'none':
            ok = False
        else:
            vu = date.fromisoformat(r['minor_consent_valid_until'])
            if vu < AUDIT:
                ok = False
            ct = r['minor_consent_type']
            if ct == 'basic':
                if dist not in ('personal_only', 'client_internal'):
                    ok = False
            elif ct == 'publicity':
                pass  # covers all
        if not ok:
            findings.append('MISSING_MINOR_CONSENT')

    # §6 commercial distribution
    if dist in ('social_public', 'print_for_sale'):
        acct = accs[r['account_id']]
        if not acct_clears_channel(acct, dist):
            findings.append('COMMERCIAL_DISTRIBUTION_FLAG')

    # §7 alteration disclosure
    if r['alteration_level'] == 'substantive' and dist in ('social_public', 'print_for_sale'):
        if r['alteration_disclosure_on_file'] != 'True':
            findings.append('ALTERATION_DISCLOSURE_MISSING')

    results[rid] = findings

# Print audit
for r in reqs:
    rid = r['request_id']
    f = results[rid]
    print(rid, '|'.join(f) if f else 'none')

# Counts
flagged = [rid for rid in results if results[rid]]
print("\n--- COUNTS ---")
print("request_count", len(reqs))
print("account_count", len(accs))
print("flagged_count", len(flagged))
print("compliant_count", len(reqs) - len(flagged))
ft = sum(len(results[rid]) for rid in results)
print("finding_total", ft)
print("character_count", sum(1 for rid in results if 'UNLICENSED_CHARACTER_USE' in results[rid]))
print("background_count", sum(1 for rid in results if 'THIRD_PARTY_BACKGROUND_UNLICENSED' in results[rid]))
print("consent_count", sum(1 for rid in results if 'MISSING_MINOR_CONSENT' in results[rid]))
print("commercial_count", sum(1 for rid in results if 'COMMERCIAL_DISTRIBUTION_FLAG' in results[rid]))
print("disclosure_count", sum(1 for rid in results if 'ALTERATION_DISCLOSURE_MISSING' in results[rid]))

# §8 escalations
print("\n--- ACCOUNTS ---")
for aid in sorted(accs):
    acct_reqs = [r for r in reqs if r['account_id'] == aid]
    flagged_n = sum(1 for r in acct_reqs if results[r['request_id']])
    maxf = max((len(results[r['request_id']]) for r in acct_reqs), default=0)
    esc = flagged_n >= 2 or maxf >= 3
    print(aid, accs[aid]['account_type'], "reqs", len(acct_reqs), "flagged", flagged_n, "maxf", maxf, "ESC" if esc else "none")

